{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C21"],
      "claim": "In patients with liver cirrhosis, oral d,l-verapamil had an absolute bioavailability of 52 ± 13%, supporting F ≥ 20% for a structurally related dimethoxyphenyl basic amine.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Valbenazine, a dimethoxy-tetrahydroisoquinoline-related drug, has an absolute oral bioavailability of approximately 49% in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Donepezil, a dimethoxyphenyl CNS drug with a basic amine, has an absolute oral bioavailability of 100% in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "In normal subjects, the (+)-isomer of pseudoracemic verapamil had a mean absolute bioavailability of 50.0%, indicating high oral bioavailability for verapamil-like structures.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Tetrabenazine showed very low oral systemic availability (mean 4.9%) in patients, but this evidence has very low assay-transfer to the query and is outweighed by higher-transfer analogues.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C33"],
      "claim": "Almorexant had an absolute oral bioavailability of 11.2% in healthy subjects, but its assay-transfer to the query is very low.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "High-transfer human absolute bioavailability data from verapamil (~50%), valbenazine (~49%), and donepezil (~100%) support F ≥ 20%. Low-F tetrabenazine and almorexant have very low transferability and do not override. The physicochemical prior is mixed but not decisive.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability measurement for the query molecule.",
    "Verapamil high-F data are partly from cirrhosis patients; normal-condition F is more variable (20-50%).",
    "Tetrabenazine low-F evidence has high structural similarity but very low assay-transfer; its relevance is uncertain.",
    "Query's metabolic stability and first-pass extraction are not experimentally characterized."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

